  "settings.discord.richPresence": "Rich Presence",
  "settings.discord.richPresenceHint": "Afficher sur votre profil Discord la partie que vous hébergez ou jouez.",
  "settings.discord.disallowJoinsVia": "Interdire de rejoindre via Discord",
  "settings.discord.disallowJoinsViaHint": "Garder le statut visible, mais retirer le bouton Rejoindre pour que personne n'entre dans votre salon depuis Discord.",
  "settings.steam.presence": "Statut Steam",
  "settings.steam.presenceHint": "Pendant une partie, Steam vous montre en train de jouer à Forged Alliance et compte les heures ; le client ouvert ne compte pas. Steam doit tourner et Forged Alliance être dans votre bibliothèque. Désactivé tant que vous ne l'activez pas.",
  "settings.steam.confirmButton": "Activer",
  "settings.steam.confirmTitle": "Activer le statut Steam ?",
  "settings.steam.confirmBody": "Le client chargera la bibliothèque Steamworks de Valve, au code fermé, pendant vos parties. Elle indique à Steam quand vous jouez à Forged Alliance sur FAF, et nous ne pouvons pas vérifier ce qu'elle pourrait envoyer d'autre à Valve.",
  "settings.steam.trustClosed": "Pour cela, le client doit charger la bibliothèque Steamworks de Valve, dont le code est fermé. Nous choisissons les fonctions appelées, seulement trois (démarrer, maintenir, arrêter), mais nous ne pouvons ni voir ni vérifier ce que la bibliothèque fait ou envoie à Valve. L'activer, c'est faire confiance à Valve sur ce point.",
  "settings.steam.trustCalls": "Le client indique seulement à Steam que vous avez commencé et arrêté de jouer à Forged Alliance. Steam sait alors quel compte a joué, de quand à quand, et l'affiche à vos amis selon vos propres réglages de confidentialité Steam. FAF est un client à part : sans ce réglage, Steam ne sait pas quand vous jouez sur FAF.",
  "settings.steam.trustTitle": "Ce que cela envoie, et ce que nous ne pouvons pas vérifier",

